// Índices que se calculan una sola vez: qué especies salen de cada una al evolucionar y qué especies forman cada cadena evolutiva
const EVO_KIDS = new Map(), CHAINS = new Map();
INFO.forEach((x, i) => {
  const n = i + 1, chain = x[12], from = x[13];   // cadena evolutiva y especie de la que evoluciona
  if (from) { if (!EVO_KIDS.has(from)) EVO_KIDS.set(from, []); EVO_KIDS.get(from).push(n); }
  if (!CHAINS.has(chain)) CHAINS.set(chain, []); CHAINS.get(chain).push(n);
});
